[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath,[switch]$BindingSmokeOnly)
$ErrorActionPreference='Stop';if ([string]::IsNullOrWhiteSpace($ProjectPath) -or -not [IO.Path]::IsPathRooted($ProjectPath)) { throw 'An explicit absolute ProjectPath is required.' };$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output('BINDING-SMOKE-PASSED|Open-Gate10RAttempt4Resume1V4|'+$ProjectPath);exit 0}
$research=Join-Path $ProjectPath 'Research';$root=Join-Path $research 'Verification\Gate10R_ProcessReuse_5pct\v4';$failureReceiptPath=Join-Path $root 'Gate10R_Attempt4_OfficialExecution1_Failure_Receipt.v4.json';$partialManifestPath=Join-Path $root 'Gate10R_Attempt4_OfficialExecution1_Partial_Manifest.v4.json';$resumeProvenancePath=Join-Path $research 'Gate10R_ProcessReuse_5pct_Attempt4_Resume1_Provenance.v4.3.json';$receiptPath=Join-Path $root 'Gate10R_Attempt4_Resume1_Receipt.v4.3.json';$checkpointPath=Join-Path $root 'gate10r-attempt4-resume1-open.checkpoint.v4.3.json'
function Get-LowerSha([string]$Path){(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant()}
function Write-AtomicJson([string]$Path,$Value){if(Test-Path -LiteralPath $Path){throw "Refusing overwrite: $Path"};$json=($Value|ConvertTo-Json -Depth 40).Replace("`r`n","`n").Replace("`r","`n");if(-not$json.EndsWith("`n",[StringComparison]::Ordinal)){$json+="`n"};$tmp=$Path+'.tmp-'+[guid]::NewGuid().ToString('N');$encoding=New-Object Text.UTF8Encoding($false,$true);[IO.File]::WriteAllText($tmp,$json,$encoding);[IO.File]::Move($tmp,$Path)}
foreach($path in @($failureReceiptPath,$partialManifestPath,$resumeProvenancePath)){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "Required resume input missing: $path"}}
if (@(Get-Process Unity -ErrorAction SilentlyContinue).Count -ne 0 -or (Test-Path -LiteralPath (Join-Path $ProjectPath 'Temp\UnityLockfile'))) { throw 'Unity or project lock is present.' }
$failure=Get-Content -LiteralPath $failureReceiptPath -Raw -Encoding UTF8|ConvertFrom-Json;$resumeProvenance=Get-Content -LiteralPath $resumeProvenancePath -Raw -Encoding UTF8|ConvertFrom-Json
if ([string]$failure.status -ne 'FAILED-ATOMICALLY-CLOSED-RESUME-AUTHORIZED' -or [string]$failure.resumeStartGate -ne 'block-verification') { throw 'Failure receipt does not authorize this resume.' }
$unit=Get-Content -LiteralPath (Join-Path $root 'UnitTests.summary.json') -Raw -Encoding UTF8|ConvertFrom-Json;$compile=Get-Content -LiteralPath (Join-Path $root 'Compile\attempt4.summary.json') -Raw -Encoding UTF8|ConvertFrom-Json;$telemetry=Get-Content -LiteralPath (Join-Path $root 'TelemetryProbe\v1.summary.json') -Raw -Encoding UTF8|ConvertFrom-Json
if ($unit.passed -ne $true -or $compile.passed -ne $true -or $telemetry.passed -ne $true) { throw 'Preserved predecessor gate is not passing.' }
if(Test-Path -LiteralPath (Join-Path $root 'Fixtures\v2')){throw 'Resume fixture root already exists.'};if(Test-Path -LiteralPath (Join-Path $root 'BlockVerification.resume1.summary.json')){throw 'Resume block summary already exists.'};if(@(Get-ChildItem -LiteralPath (Join-Path $root 'Fixtures\v1') -Recurse -File -ErrorAction SilentlyContinue).Count -ne 0){throw 'Failed block attempt unexpectedly produced files.'}
$bindingErrors=New-Object Collections.Generic.List[string];foreach($reference in @($resumeProvenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$reference.relativePath).Replace('/','\');if(-not(Test-Path -LiteralPath $path -PathType Leaf)){$bindingErrors.Add('missing:'+$reference.relativePath)}elseif((Get-LowerSha $path) -ne [string]$reference.sha256){$bindingErrors.Add('hash:'+$reference.relativePath)}};if($bindingErrors.Count -ne 0){throw "Resume provenance binding failed: $($bindingErrors -join '; ')"}
$receipt=[ordered]@{schemaVersion=1;receiptId='gate10r-attempt4-resume1-one-use-receipt-v4.3';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='CONSUMED-FOR-ONE-OFFICIAL-GATE10R-RESUME';attempt=4;resumeOrdinal=1;startGate='block-verification';preservedPassingGates=@('unit','compile','telemetry');failureReceipt=[ordered]@{relativePath='Research/Verification/Gate10R_ProcessReuse_5pct/v4/Gate10R_Attempt4_OfficialExecution1_Failure_Receipt.v4.json';sha256=Get-LowerSha $failureReceiptPath};partialManifest=[ordered]@{relativePath='Research/Verification/Gate10R_ProcessReuse_5pct/v4/Gate10R_Attempt4_OfficialExecution1_Partial_Manifest.v4.json';sha256=Get-LowerSha $partialManifestPath};resumeProvenance=[ordered]@{relativePath='Research/Gate10R_ProcessReuse_5pct_Attempt4_Resume1_Provenance.v4.3.json';sha256=Get-LowerSha $resumeProvenancePath};maximumExecutionsForThisReceipt=1;overwriteAllowed=$false;formalCampaign=$false;gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $receiptPath $receipt
$checkpoint=[ordered]@{schemaVersion=1;checkpointKind='gate10r-attempt4-resume1-open-v4.3';savedAtUtc=[DateTime]::UtcNow.ToString('o');status='GATE10R-ATTEMPT4-RESUME1-OPEN-BLOCK-GATE-NEXT';receiptSha256=Get-LowerSha $receiptPath;resumeOrdinal=1;startGate='block-verification';unityStarted=$false;gate11RAuthorized=$false;gate12RAuthorized=$false;gate13RAuthorized=$false};Write-AtomicJson $checkpointPath $checkpoint
$checkpoint|ConvertTo-Json -Depth 12
